// ─── timeline: section/line lookups, subtitles, header, transitions ─────────
// window.TL is generated by tools/build_timeline.py from the synthesized voice:
//   { dur, sections: [{ id, title, t0, t1, lines: [{ sub, t0, t1, ch: [start time per char] }] }] }

const SEC = {};
const SCENES = {};
function initTimeline() {
  TL.sections.forEach((s, i) => {
    s.index = i;
    // start time of line i (negative i counts from the end)
    s.L = (i) => s.lines[(i + s.lines.length) % s.lines.length].t0;
    s.E = (i) => s.lines[(i + s.lines.length) % s.lines.length].t1;
    // time the n-th occurrence of `str` starts being spoken in line i
    s.at = (i, str, n = 0) => {
      const ln = s.lines[(i + s.lines.length) % s.lines.length];
      let p = -1; for (let k = 0; k <= n; k++) p = ln.sub.indexOf(str, p + 1);
      return p < 0 ? ln.t0 : ln.ch[p];
    };
    // time the given substring finishes
    s.after = (i, str) => {
      const ln = s.lines[(i + s.lines.length) % s.lines.length];
      const p = ln.sub.indexOf(str); if (p < 0) return ln.t1;
      const q = p + str.length; return q < ln.ch.length ? ln.ch[q] : ln.t1;
    };
    SEC[s.id] = s;
  });
}

function sectionAt(t) {
  const S = TL.sections; for (let i = S.length - 1; i >= 0; i--) if (t >= S[i].t0) return S[i]; return S[0];
}
function lineAt(t) {
  for (const s of TL.sections) for (let i = 0; i < s.lines.length; i++) {
    const l = s.lines[i], next = s.lines[i + 1];
    const end = Math.min(l.t1 + 0.45, next ? next.t0 : s.t1);
    if (t >= l.t0 - 0.05 && t < end) return l;
  }
  return null;
}

// split a subtitle into ≤2 balanced rows at punctuation
// br: break index precomputed by tools/build_timeline.py (word-aware); the rule below is the fallback
function splitSub(s, br) {
  const max = 15;
  if (s.length <= max) return [s];
  if (br > 0 && br < s.length) return [s.slice(0, br), s.slice(br)];
  let best = -1, bestScore = 1e9;
  for (let i = 4; i < s.length - 3; i++) {
    if ('，、：；。！？ '.includes(s[i])) {
      const a = i + 1, score = Math.abs(a - (s.length - a));
      if (score < bestScore) { bestScore = score; best = a; }
    }
  }
  if (best < 0 || Math.max(best, s.length - best) > max + 4) best = Math.ceil(s.length / 2);
  return [s.slice(0, best), s.slice(best)];
}
// position (seconds) inside 前へススメ at time t, from the music plan
function songPos(t) {
  let pos = 0;
  for (const m of TL.music) if (m.track === 'maesusume' && t >= m.t0) pos = m.src + (t - m.t0);
  return pos;
}
